package kernels

// gemm32 is the float32 GEMM on the NEON 8x8 kernel (gemmMicro8x8S in
// sum_arm64.s, generated by go-asmgen; see asmgen/arm64/gen.go).
var gemm32 = &gemmKernel[float32]{mr: 8, nr: 8, micro: gemmMicro32}

// gemmMicro32 adds the 8 x 8 tile sum_p pa[p*8..]*pb[p*8..] into the C block at
// dst[0:], whose rows are ldc apart. pa, pb hold at least kc*8 packed
// (zero-padded) floats; dst has at least 7*ldc + 8 elements.
func gemmMicro32(kc int, pa, pb, dst []float32, ldc int) {
	_, _, _ = pa[kc*8-1], pb[kc*8-1], dst[7*ldc+7] // the kernel's whole reach
	gemmMicro8x8S(kc, &pa[0], &pb[0], &dst[0], ldc)
}

